// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.undoimport timber.log.Timberimport com.roshan.persona.brain.skill.SystemOperationimport com.roshan.persona.database.dao.UndoActionDaoimport com.roshan.persona.database.entity.UndoActionEntityimport com.roshan.persona.system.handler.ReversibleHandler/** * NOUS — Persistent Undo Stack (Module 10 v2 — Review 1 + Review 2 Fix A). * * Room DB-backed LIFO stack of reversible system operations. Survives app * restart — user can say "NOUS, undo that" even after killing and reopening * the app. * * ## v2 design (per strategy) * *  - **Pre-state, not inverse** (Review 2 Fix A): Each entry stores the *    state captured BEFORE the operation executed. Undo restores that exact *    state — not the inverse operation. This avoids state desync when the *    user manually changed the state after NOUS's action. * *  - **Per-handler serialization** (audit defect B fix): Pre-state JSON is *    produced by the handler's own [ReversibleHandler.serializePreState] *    method, so data-class pre-states (`VolumePreState`, `TorchPreState`, *    etc.) round-trip correctly. The legacy [SystemOperationSerializer] *    primitive fallback is used only when no handler is registered for the *    action's `handlerId` (e.g., unit tests with primitive preStates). * *  - **Bounded size**: Only the last [MAX_UNDO_ACTIONS] (50) entries are kept. *    Older entries are trimmed on each push. Prevents unbounded DB growth. * *  - **Two-phase pop**: [pop] returns the latest action WITHOUT deleting it. *    [confirmPop] deletes it after the undo successfully restores state. *    If undo fails (e.g., hardware unavailable), the entry stays so the user *    can retry. * *  - **Serializer-backed**: Operations are serialized to JSON via *    [SystemOperationSerializer] for Room storage. This decouples the *    undo stack from the SystemOperation sealed class hierarchy. * * ## Lifecycle * * ``` * 1. Executor executes operation successfully. * 2. Executor calls PersistentUndoStack.push(action). * 3. Stack inserts a row + trims to last 50. * 4. User says "NOUS, undo that". * 5. SystemFacade calls PersistentUndoStack.pop() → ReversibleAction. * 6. SystemFacade calls handler.restorePreState(action.operation, action.preState). * 7. On success: SystemFacade calls PersistentUndoStack.confirmPop(). * 8. Stack deletes the row. * ``` * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Persistent Undo Stack</a> */class PersistentUndoStack(    private val dao: UndoActionDao,    private val serializer: SystemOperationSerializer = SystemOperationSerializer,    /**     * Handler registry keyed by handler ID, used for per-handler pre-state     * (de)serialization (audit defect B fix). Defaults to empty — legacy     * callers (tests with primitive preStates) still work via the     * [SystemOperationSerializer] primitive fallback.     */    private val handlerRegistry: Map<String, ReversibleHandler<*>> = emptyMap(),) {    /**     * Push a reversible action onto the stack.     *     * @param action the action to store (operation + pre-state + description).     * @return the row ID of the inserted action (for diagnostics).     */    suspend fun push(action: ReversibleAction): Long {        val operationJson = try {            serializer.serializeOperation(action.operation)        } catch (t: Throwable) {            Timber.tag(TAG).w("Failed to serialize operation ${action.operation::class.simpleName}", t)            return -1L        }        val preStateJson = try {            serializePreStateWithHandler(action.handlerId, action.preState)        } catch (t: Throwable) {            Timber.tag(TAG).w("Failed to serialize pre-state", t)            null        }        val entity = UndoActionEntity(            operationType = action.operation::class.simpleName ?: "Unknown",            operationJson = operationJson,            preStateJson = preStateJson,            handlerId = action.handlerId,            timestampMs = action.timestampMs,            description = action.description,        )        val id = dao.insert(entity)        dao.trim(MAX_UNDO_ACTIONS)        Timber.tag(TAG).d("Pushed undo action: type=${entity.operationType}, id=$id, total=${dao.count()}.")        return id    }    /**     * Pop the latest reversible action WITHOUT deleting it.     *     * Call [confirmPop] after the undo successfully restores state. If undo     * fails, the action stays on the stack so the user can retry.     *     * @return the latest action, or null if the stack is empty.     */    suspend fun pop(): ReversibleAction? {        val entity = dao.getLatest() ?: return null        return entityToAction(entity)    }    /**     * Confirm that a [pop] was successfully undone — delete the popped entry.     *     * @param id the row ID returned by [pop] (via [ReversibleAction.id]).     */    suspend fun confirmPop(id: Long) {        dao.deleteById(id)        Timber.tag(TAG).d("Confirmed pop — deleted undo action id=$id.")    }    /**     * Peek at the latest action without popping it.     *     * Used by the UI to show "Last action: Torch turned on — undo?".     */    suspend fun peek(): ReversibleAction? {        val entity = dao.getLatest() ?: return null        return entityToAction(entity)    }    /**     * Get the last [limit] actions for the UI history list.     *     * Returns most-recent-first.     */    suspend fun getRecent(limit: Int = MAX_UNDO_ACTIONS): List<ReversibleAction> {        return dao.getRecent(limit).mapNotNull { entityToAction(it) }    }    /** Number of actions currently on the stack. */    suspend fun count(): Int = dao.count()    /** Clear all undo actions (Settings → Privacy → Clear action history). */    suspend fun clear() {        val n = dao.count()        dao.clear()        Timber.tag(TAG).i("Cleared $n undo actions.")    }    // ──────────────────────────────────────────────────────────────────────    private fun entityToAction(entity: UndoActionEntity): ReversibleAction? {        return try {            val operation = serializer.deserializeOperation(entity.operationJson)            val preState = deserializePreStateWithHandler(entity.handlerId, entity.preStateJson)            ReversibleAction(                id = entity.id,                operation = operation,                preState = preState,                handlerId = entity.handlerId,                timestampMs = entity.timestampMs,                description = entity.description,            )        } catch (t: Throwable) {            Timber.tag(TAG).w("Failed to deserialize undo action id=${entity.id}", t)            null        }    }    /**     * Serialize a pre-state value via the handler that produced it (if registered),     * falling back to [SystemOperationSerializer]'s primitive handling.     */    private fun serializePreStateWithHandler(handlerId: String, preState: Any?): String? {        val handler = handlerRegistry[handlerId]        return if (handler != null) {            handler.serializePreState(preState)        } else {            serializer.serializePreState(preState)        }    }    /**     * Deserialize a pre-state JSON via the handler that produced it (if registered),     * falling back to [SystemOperationSerializer]'s primitive handling.     */    private fun deserializePreStateWithHandler(handlerId: String, json: String?): Any? {        val handler = handlerRegistry[handlerId]        return if (handler != null) {            handler.deserializePreState(json)        } else {            serializer.deserializePreState(json)        }    }    companion object {        private const val TAG = "PersistentUndoStack"        /** Maximum number of undo actions kept (LIFO + bounded). */        const val MAX_UNDO_ACTIONS = 50    }}// ──────────────────────────────────────────────────────────────────────────/** * One reversible action stored on the [PersistentUndoStack]. * * @param id           row ID in the undo_actions table (for [PersistentUndoStack.confirmPop]). * @param operation    the operation that was executed (e.g., SetVolume(80)). * @param preState     the state captured BEFORE execution (e.g., 50 = previous volume). *                     Restore this via `handler.restorePreState(operation, preState)`. * @param handlerId    the handler that executed the operation (e.g., "volume"). * @param timestampMs  when the operation was executed. * @param description  human-readable description for the undo UI. */data class ReversibleAction(    val id: Long,    val operation: SystemOperation,    val preState: Any?,    val handlerId: String,    val timestampMs: Long,    val description: String,)